window.COURSE_PROJECT = {"id":"java-g19-intro","files":[{"path":"README.md","language":"Markdown","content":"# Introducción a Java · G19\n\nEjemplos y ejercicios de la primera semana del curso, organizados por tema. El proyecto usa Java 21 y está preparado como módulo sencillo de IntelliJ IDEA; no requiere Maven ni Gradle.\n\n## Abrir el proyecto\n\n1. Descarga el ZIP desde la página del proyecto y descomprímelo. Contiene solo este proyecto.\n2. Abre la carpeta `java-g19-intro` en IntelliJ IDEA. Incluye el módulo `javag19_semana1.iml`.\n3. Instala o selecciona un JDK 21 en la configuración del proyecto.\n4. Dentro de `src`, elige una clase que tenga `main` y ejecútala con el botón junto al método.\n\n## Contenido\n\n- `src/variables/`: variables y ejercicios de entrada, operaciones y datos.\n- `src/condicionales/`: comparaciones, operadores lógicos y decisiones.\n- `src/arrays/`: arrays y operaciones básicas de `ArrayList`.\n- `src/loops/`: bucles y ejercicios de repetición.\n\nLos archivos `.class` generados al compilar se excluyen del proyecto; IntelliJ puede volver a generarlos al ejecutar el código.\n","bytes":1009},{"path":"src/arrays/Teoria.java","language":"Java","content":"package arrays;\n\nimport java.util.ArrayList;\nimport java.util.Arrays;\n\npublic class Teoria {\n    public static void main(String[] args) {\n        // declarar un array\n        int[] numeros = new int[10];\n        System.out.println(\"==============ARRAY ANTES DEL CAMBIO====================\");\n        System.out.println(Arrays.toString(numeros));\n        numeros[5] = 24;\n        System.out.println(\"==============ARRAY DESPUS DEL CAMBIO===================\");\n        System.out.println(Arrays.toString(numeros));\n\n        // acceder y imprimir un elemento de un array\n        System.out.println(\"=============IMPRIMIENDO UN VALOR DEL ARRAY================\");\n        System.out.println(numeros[5]);\n        int var1 = numeros[5];\n        System.out.println(var1);\n\n        // crear un array segunda forma\n\n        String[] nombres = {\"George\", \"Sheyla\", \"Juan\", \"Maria\", \"Jose\", \"Julio\", \"Fiorela\"};\n\n        System.out.println(Arrays.toString(nombres));\n\n        // crear array de strings de la manera 1\n\n        String[] estudiantes = new String[20];\n        estudiantes[0] = \"George\";\n\n        // tener cuidado\n\n//       estudiantes[20] = \"Jose\"; // error\n\n        // Los arrays son estaticos --> No se puede aumentar ni disminuir el tamanio\n\n    }\n}\n","bytes":1254},{"path":"src/arrays/TeoriaArrayList.java","language":"Java","content":"package arrays;\n\nimport java.util.ArrayList;\n\npublic class TeoriaArrayList {\n    public static void main(String[] args) {\n        ArrayList\u003cString> nombres = new ArrayList\u003c>();\n        // agregar elementos\n        nombres.add(\"George\");\n        nombres.add(\"Sheyla\");\n        nombres.add(\"Jose\");\n\n        System.out.println(\"======================ARRAY ELEMENTOS========================\");\n        System.out.println(nombres);\n        // obtener por indice\n        System.out.println(nombres.get(1));\n\n        // actualizar\n\n        nombres.set(2, \"Fiorela\");\n        System.out.println(\"===================ARRAY DESPUES DE LOS CAMBIOS===================\");\n        System.out.println(nombres);\n\n        // remover\n        // remueve por indice\n        nombres.remove(0);\n\n        System.out.println(\"===================ARRAY DESPUES DE REMOVER===================\");\n        System.out.println(nombres);\n\n        // remueve por elemento. Si lo encuentra lo borra, si no no hace nada\n        // [Sheyla, Fiorela]\n        nombres.remove(\"Fiorela\");\n        System.out.println(nombres);\n    }\n}\n","bytes":1093},{"path":"src/condicionales/Teoria.java","language":"Java","content":"package condicionales;\n\nimport java.util.Scanner;\n\npublic class Teoria {\n    public static void main(String[] args) {\n        // operadores de comparacion\n        // resultado booleano\n        // valor numerico OPERADOR valor numerico -> respuesta booleana\n        System.out.println(5 > 3);\n        System.out.println(5 >= 5);\n        System.out.println(5 == 5);\n        System.out.println(5 == 3);\n        System.out.println(5 != 4);\n\n        // operadores logicos\n        // AND, OR, NOT\n        // resultado booleano\n        // valor booleano OPERADOR valor booleano -> respuesta booleana\n\n        // AND\n\n        System.out.println(\"OPERADORES DE COMPARACION\");\n        System.out.println(\"================OPERADOR AND=======================\");\n        System.out.println(true && true);\n        System.out.println(true && false);\n\n        System.out.println(\"================OPERADOR OR========================\");\n        System.out.println(true || false);\n        System.out.println(false || true);\n        System.out.println(false || false);\n\n        System.out.println(\"================OPERADOR NOT======================\");\n        System.out.println(!true);\n        System.out.println(!false);\n\n\n        System.out.println(\"===============CONDICIONALES======================\");\n        System.out.println(\"Ingrese la edad del usuario\");\n        Scanner sc = new Scanner(System.in);\n        int edad = sc.nextInt();\n        if(edad >= 18) {\n            System.out.println(\"Enviar la pelicula como recomendacion\");\n        } else {\n            System.out.println(\"Buscar otra pelicula como recomendacion\");\n        }\n\n\n    }\n}\n","bytes":1634},{"path":"src/condicionales/ejercicios/Ejercicio1.java","language":"Java","content":"package condicionales.ejercicios;\n\nimport java.util.Scanner;\n\npublic class Ejercicio1 {\n    public static void main(String[] args) {\n        // pedir un numero aleatoria a el usuario y determinar si es par o impar\n        // %\n        Scanner sc = new Scanner(System.in);\n        System.out.println(\"Ingrese el numero\");\n        int numero = sc.nextInt();\n        if(numero % 2 == 0) {\n            System.out.println(\"El numero es par\");\n        } else {\n            System.out.println(\"El numero es impar\");\n        }\n    }\n}\n","bytes":527},{"path":"src/loops/Teoria.java","language":"Java","content":"package loops;\n\npublic class Teoria {\n    public static void main(String[] args) {\n        for(int i = 1; i \u003c=10; i++) {\n            System.out.println(i);\n        }\n\n        for(int i = 1; i \u003c=10; i+=2) {\n            System.out.println(i);\n        }\n\n        int contador = 1;\n        while(contador \u003c=10) {\n            System.out.println(\"Contador menor a 10\");\n            contador++;\n        }\n\n        System.out.println(\"===================OPERADOR ++ ==========================\");\n        int  a = 10;\n        a++; // suma 1 al valor de a --> 11\n        ++a; // representa lo mismo\n\n\n        int b = 10;\n        // ++ antes (++b==10) significa primero sumar y luego hacer la comparacion\n        // ++ despues (b++==10) primero realiza la comparacion y luego suma\n        if(b==10) {\n            System.out.println(\"El valor de B es \" + b);\n            System.out.println(\"Ingresamos a la condicion if\");\n        } else {\n            System.out.println(\"El valor de B ya no es 10\");\n        }\n\n    }\n}\n\n// imprimir los numeros del 2 al 100\n// imprimir solo los numeros pares\n// imprimir los numeros del 100 al cero (reversa) 100, 99, 98, ..., 3, 2, 1, 0\n// verificar si un numero es primo (solo divisible entre el mismo y la unidad)\n// ejemplo 7 solo se puede dividir entre 7 y 1\n// ejemplo 11 solo se puede dividir entre 11 y 1\n","bytes":1335},{"path":"src/loops/ejercicios/Ejercicio1.java","language":"Java","content":"package loops.ejercicios;\n\npublic class Ejercicio1 {\n    public static void main(String[] args) {\n\n    }\n}\n","bytes":107},{"path":"src/variables/Hello.java","language":"Java","content":"package variables;\n\npublic class Hello {\n    public static void main(String[] args) {\n        System.out.println(\"variables.Hello World!\");\n        System.out.println(\"Hola Mundo!\" + \" En Java\");\n\n        // String nombreCompleto = \"George Maxi\"; error no se pueden tener dos variables con el mismo nombre\n        // comentario de todo un bloque\n        /*\n        String var1 = \"Test\";\n        int var2 = 232;\n        boolean var3 = false;\n        */\n\n        String nombreCompleto = \"George Maxi Ccapa\";\n        int edad = 29;\n        // M significa masculino y F feminino\n        char sexo = 'M';\n        float estatura = 1.7f;\n        String ciudad = \"Arequipa\";\n\n        System.out.println(\"Hola soy \" + nombreCompleto + \" tengo \" + edad + \" y soy de \" + ciudad);\n\n        // operaciones con variables\n\n        int a = 10;\n        int b = 20;\n\n        int resultado = a + b; // 30\n        System.out.println(resultado);\n\n        String cadena1 = \"Hola \";\n        String cadena2 = \"mundo\";\n        // concatenacion de cadenas\n        // Solo se puede usar el operador + para operaciones con String\n        // operadores como -, *, / no funcionan y daran error\n        String respuestaCadenas = cadena1 + cadena2;\n        System.out.println(respuestaCadenas);\n\n        // division\n\n        float numero1 = 30;\n        float numero2 = 9;\n        // int / int --> int\n        // float / int --> float\n        // int / float --> float\n        // float / float --> float\n//        int respuesta = numero1 / numero2; error\n        System.out.println(\"El resultado es: \" + numero1/numero2);\n\n\n        int var1 = 10;\n        var1 = 20;\n        var1 = var1+5; // var1+=5\n\n        int mensajesSinLeer = 3;\n        // te llega un nuevo mensaje\n        mensajesSinLeer = mensajesSinLeer + 1; // 4\n        // lees todos los mensajes\n        mensajesSinLeer = 0;\n    }\n}\n","bytes":1861},{"path":"src/variables/ejercicios/Ejercicio1.java","language":"Java","content":"package variables.ejercicios;\nimport java.util.Scanner;\n\npublic class Ejercicio1 {\n    public static void main(String[] args) {\n        // Implementar un programa que calcule el area de un circulo\n        Scanner sc = new Scanner(System.in);\n\n        System.out.println(\"Ingrese el valor del radio\");\n        System.out.println(\"Holllllaaa\");\n\n        double radio = sc.nextDouble();\n        double areaCirculo = Math.PI * radio * radio;\n\n        System.out.println(areaCirculo);\n    }\n}\n","bytes":488},{"path":"src/variables/ejercicios/Ejercicio2.java","language":"Java","content":"package variables.ejercicios;\n\n\nimport java.util.Scanner;\n\npublic class Ejercicio2 {\n    public static void main(String[] args) {\n        // dividir dos numeros y imprimir el resultado\n        Scanner sc = new Scanner(System.in);\n        System.out.println(\"Ingrese el primer numero\");\n        double num1 = sc.nextDouble();\n        System.out.println(\"Ingrese el segundo numero\");\n        double num2 = sc.nextDouble();\n\n        double resultado = num1 / num2;\n\n        System.out.println(resultado);\n\n\n    }\n}\n","bytes":512},{"path":"src/variables/ejercicios/Ejercicio3.java","language":"Java","content":"package variables.ejercicios;\n\npublic class Ejercicio3 {\n    public static void main(String[] args) {\n        // recibir una temperatura en celsius y convertirla a farenheit\n        // F = C * (9/5) + 32\n    }\n}\n","bytes":212}],"sourceCount":10,"archive":"java-g19-intro.zip","archiveBytes":7694,"revision":"fb2fc30d7816"};
